package com.tvfs.app.data.parser

import com.tvfs.app.data.db.ChannelEntity
import org.json.JSONObject

data class ParsedSeniorTvConfig(
    val generatedAt: String,
    val totalChannels: Int,
    val channels: List<ChannelEntity>
)

object SeniorTvConfigParser {

    /**
     * Parses the UTF-8 JSON content of `seniortv_config.json` generated by XC-PLaPA.
     */
    fun parse(jsonContent: String): ParsedSeniorTvConfig {
        val root = JSONObject(jsonContent)
        val generatedAt = root.optString("generated_at", "")
        val channelsArray = root.optJSONArray("channels") ?: org.json.JSONArray()
        val totalChannels = root.optInt("total_channels", channelsArray.length())

        val channelList = ArrayList<ChannelEntity>(channelsArray.length())
        for (i in 0 until channelsArray.length()) {
            val obj = channelsArray.optJSONObject(i) ?: continue
            val channelNumber = obj.optInt("channel_number", i + 1)
            val name = obj.optString("name", "Channel $channelNumber").trim()
            val streamUrl = obj.optString("stream_url", "").trim()
            val logoRaw = obj.optString("logo", "").trim()
            val logo = if (logoRaw.isNotEmpty()) logoRaw else null
            val epgId = obj.optString("epg_id", "").trim()
            val group = obj.optString("group", "General").trim()

            channelList.add(
                ChannelEntity(
                    channelNumber = channelNumber,
                    name = name,
                    streamUrl = streamUrl,
                    logo = logo,
                    epgId = epgId,
                    groupName = group,
                    isFavorite = false,
                    sortOrder = i
                )
            )
        }

        return ParsedSeniorTvConfig(
            generatedAt = generatedAt,
            totalChannels = totalChannels,
            channels = channelList
        )
    }
}
